     1→"use client";
     2→
     3→import { ReactNode, useState, useEffect, useRef } from "react";
     4→import { useAuth } from "@/contexts/AuthContext";
     5→import { useRouter } from "next/navigation";
     6→import { Button, Avatar } from "@/components/ui";
     7→import DirectMessages from "@/components/DirectMessages";
     8→import Channels from "@/components/Channels";
     9→import { TeamMember } from "@/types";
    10→import { Channel } from "@/types/channel";
    11→import { useUnreadCount } from "@/hooks/useUnreadCount";
    12→import { useUnreadStore } from "@/store/unreadStore";
    13→import { useMarkAllAsRead } from "@/hooks/useMarkAllAsRead";
    14→import { LogOut, Settings, CheckCheck } from "lucide-react";
    15→import SearchBox from "@/components/SearchBox";
    16→
    17→interface DashboardLayoutProps {
    18→  children: ReactNode;
    19→  channels?: Channel[];
    20→  selectedChannelId?: string;
    21→  joinedChannels?: string[];
    22→  selectedDirectMessageId?: string;
    23→  onSelectChannel?: (channelId: string) => void;
    24→  onCreateChannel?: (channel: Channel) => void;
    25→  onBrowseChannels?: () => void;
    26→  onStartChat?: (memberId: string, dmConversationId?: string) => void;
    27→  onNewChat?: () => void;
    28→  onLogout?: () => void;
    29→}
    30→
    31→export default function DashboardLayout({
    32→  children,
    33→  channels = [],
    34→  selectedChannelId,
    35→  joinedChannels = [],
    36→  selectedDirectMessageId,
    37→  onSelectChannel,
    38→  onCreateChannel,
    39→  onBrowseChannels,
    40→  onStartChat,
    41→  onNewChat,
    42→  onLogout,
    43→}: DashboardLayoutProps) {
    44→  const { user } = useAuth();
    45→  const router = useRouter();
    46→  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
    47→
    48→  // Left sidebar width state
    49→  const [sidebarWidth, setSidebarWidth] = useState(256); // Default 256px (w-64)
    50→  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
    51→  const sidebarDragStart = useRef({ x: 0, width: 256 });
    52→  const sidebarScrollRef = useRef<HTMLDivElement>(null);
    53→
    54→  // Left sidebar drag handling
    55→  const handleSidebarDragStart = (e: React.MouseEvent) => {
    56→    setIsResizingSidebar(true);
    57→    sidebarDragStart.current = { x: e.clientX, width: sidebarWidth };
    58→  };
    59→
    60→  useEffect(() => {
    61→    const handleSidebarDrag = (e: MouseEvent) => {
    62→      if (!isResizingSidebar) return;
    63→      const deltaX = e.clientX - sidebarDragStart.current.x;
    64→      const newWidth = Math.max(
    65→        180,
    66→        Math.min(400, sidebarDragStart.current.width + deltaX),
    67→      );
    68→      setSidebarWidth(newWidth);
    69→    };
    70→
    71→    const handleSidebarDragEnd = () => {
    72→      setIsResizingSidebar(false);
    73→    };
    74→
    75→    if (isResizingSidebar) {
    76→      document.addEventListener("mousemove", handleSidebarDrag);
    77→      document.addEventListener("mouseup", handleSidebarDragEnd);
    78→      document.body.style.cursor = "col-resize";
    79→      document.body.style.userSelect = "none";
    80→    }
    81→
    82→    return () => {
    83→      document.removeEventListener("mousemove", handleSidebarDrag);
    84→      document.removeEventListener("mouseup", handleSidebarDragEnd);
    85→      document.body.style.cursor = "";
    86→      document.body.style.userSelect = "";
    87→    };
    88→  }, [isResizingSidebar]);
    89→
    90→  // Sidebar scroll position persistence across route changes
    91→  useEffect(() => {
    92→    const el = sidebarScrollRef.current;
    93→    if (!el) return;
    94→
    95→    const saved = sessionStorage.getItem('sidebar-scroll-top');
    96→    if (saved) {
    97→      el.scrollTop = parseInt(saved, 10);
    98→    }
    99→
   100→    let timeoutId: NodeJS.Timeout;
   101→    const handleScroll = () => {
   102→      clearTimeout(timeoutId);
   103→      timeoutId = setTimeout(() => {
   104→        sessionStorage.setItem('sidebar-scroll-top', String(el.scrollTop));
   105→      }, 100);
   106→    };
   107→
   108→    el.addEventListener('scroll', handleScroll, { passive: true });
   109→    return () => {
   110→      el.removeEventListener('scroll', handleScroll);
   111→      clearTimeout(timeoutId);
   112→    };
   113→  }, []);
   114→
   115→  // Initialize unread count system
   116→  const { markAsRead } = useUnreadCount();
   117→  const { totalUnreadCount } = useUnreadStore();
   118→  const { markAllAsRead, isLoading: isMarkingAllRead } = useMarkAllAsRead();
   119→
   120→  // Debug: print unread count state
   121→  useEffect(() => {
   122→    console.log("📊 DashboardLayout - Total unread count:", totalUnreadCount);
   123→  }, [totalUnreadCount]);
   124→
   125→  // When selecting a channel, clear unread count
   126→  const handleSelectChannel = (channelId: string) => {
   127→    console.log("📖 Marking channel as read:", channelId);
   128→    markAsRead(channelId);
   129→    onSelectChannel?.(channelId);
   130→  };
   131→
   132→  // Mark all as read
   133→  const handleMarkAllAsRead = async () => {
   134→    if (totalUnreadCount === 0) return;
   135→    try {
   136→      const result = await markAllAsRead();
   137→      console.log("✅ Marked all as read:", result);
   138→    } catch (error) {
   139→      console.error("Failed to mark all as read:", error);
   140→    }
   141→  };
   142→
