     2→
     3→// Force dynamic rendering - because this page uses client-side state management
     4→export const dynamic = 'force-dynamic';
     5→
     6→import { useEffect, useState } from 'react';
     7→import { useRouter, useParams } from 'next/navigation';
     8→import { useAuth } from '@/contexts/AuthContext';
     9→import { Button } from '@/components/ui';
    10→import DashboardLayout from '@/components/DashboardLayout';
    11→import ChannelView from '@/components/ChannelView';
    12→import BrowseChannels from '@/components/BrowseChannels';
    13→import NewDirectMessageModal from '@/components/NewDirectMessageModal';
    14→import { Channel as ChannelType } from '@/types/channel';
    15→
    16→// Type definitions - matching API response data format
    17→interface User {
    18→  id: string;
    19→  email: string;
    20→  displayName: string;
    21→  realName?: string;
    22→  avatarUrl?: string;
    23→  isOnline: boolean;
    24→  lastSeenAt?: Date;
    25→}
    26→
    27→interface ApiChannel {
    28→  id: string;
    29→  name: string;
    30→  description?: string;
    31→  isPrivate: boolean;
    32→  createdAt: Date;
    33→  createdBy: {
    34→    id: string;
    35→    displayName: string;
    36→    avatarUrl?: string;
    37→  };
    38→  memberCount: number;
    39→  isJoined: boolean;
    40→}
    41→
    42→export default function DashboardPage() {
    43→  const { user, logout, loading } = useAuth();
    44→  const router = useRouter();
    45→  const params = useParams();
    46→  const userId = params.userId as string | undefined;
    47→
    48→  const [selectedChat, setSelectedChat] = useState<string | undefined>(undefined);
    49→  const [selectedChannel, setSelectedChannel] = useState<string | undefined>(undefined);
    50→  const [channels, setChannels] = useState<ApiChannel[]>([]);
    51→  const [joinedChannels, setJoinedChannels] = useState<string[]>([]);
    52→  const [currentView, setCurrentView] = useState<'channel' | 'browse'>('channel');
    53→  const [isNewDMModalOpen, setIsNewDMModalOpen] = useState(false);
    54→  const [users, setUsers] = useState<User[]>([]);
    55→  const [isJoiningChannel, setIsJoiningChannel] = useState<string | undefined>(undefined);
    56→
    57→  // Get channel data
    58→  useEffect(() => {
    59→    const fetchChannels = async () => {
    60→      try {
    61→        // Fetch all channels (not just joined) for browsing
    62→        const response = await fetch('/api/channels?type=all&limit=100', {
    63→          credentials: 'include'
    64→        });
    65→
    66→        if (response.ok) {
    67→          const data = await response.json();
    68→          setChannels(data.channels);
    69→
    70→          // Get joined channel IDs
    71→          const joined = data.channels
    72→            .filter((channel: ApiChannel) => channel.isJoined)
    73→            .map((channel: ApiChannel) => channel.id);
    74→          setJoinedChannels(joined);
    75→
    76→          // If no channel is selected, select the first joined channel
    77→          if (!selectedChannel && joined.length > 0) {
    78→            setSelectedChannel(joined[0]);
    79→          }
    80→        }
    81→      } catch (error) {
    82→        console.error('Error fetching channels:', error);
    83→      }
    84→    };
    85→
    86→    if (user) {
    87→      fetchChannels();
    88→    }
    89→  }, [user, selectedChannel]);
    90→
    91→  // Get user data
    92→  useEffect(() => {
    93→    const fetchUsers = async () => {
    94→      try {
    95→        const response = await fetch('/api/users', {
    96→          credentials: 'include'
    97→        });
    98→
    99→        if (response.ok) {
   100→          const data = await response.json();
   101→          setUsers(data.users);
   102→        }
   103→      } catch (error) {
   104→        console.error('Error fetching users:', error);
   105→      }
   106→    };
   107→
   108→    if (user) {
   109→      fetchUsers();
   110→    }
   111→  }, [user]);
   112→
   113→  // Listen for route changes and sync state
   114→  useEffect(() => {
   115→    if (userId && users.length > 0) {
   116→      const member = users.find(u => u.id === userId);
   117→      if (member) {
   118→        setSelectedChat(userId);
   119→        setSelectedChannel(undefined);
   120→        setCurrentView('channel');
   121→        console.log('🔄 [DEBUG] Route state sync - switching to DM:', userId);
   122→      }
   123→    } else if (!userId) {
   124→      // If no userId parameter and currently in DM mode, switch back to channel mode
   125→      if (selectedChat) {
   126→        setSelectedChat(undefined);
   127→        console.log('🔄 [DEBUG] Route state sync - switching to channel mode');
   128→      }
   129→    }
   130→  }, [userId, users, selectedChat]);
   131→
   132→  // Listen for channel value in URL parameters
   133→  useEffect(() => {
   134→    const searchParams = new URLSearchParams(window.location.search);
   135→    const channelParam = searchParams.get('channel');
   136→    const viewParam = searchParams.get('view');
   137→
   138→    if (channelParam) {
   139→      console.log('🎯 [DEBUG] Channel parameter detected:', channelParam);
   140→      // Check if channel is joined
   141→      if (joinedChannels.includes(channelParam)) {
   142→        setSelectedChannel(channelParam);
   143→        setSelectedChat(undefined);
   144→        setCurrentView('channel');
   145→        console.log('✅ [DEBUG] Channel selected:', channelParam);
   146→      } else {
   147→        console.log('⚠️ [DEBUG] Channel not joined or does not exist:', channelParam);
   148→      }
   149→    }
   150→
   151→    if (viewParam === 'browse') {
   152→      setCurrentView('browse');
   153→      setSelectedChat(undefined);
   154→      console.log('🔍 [DEBUG] Switching to browse channels view');
   155→    }
   156→  }, [joinedChannels]);
   157→
   158→  useEffect(() => {
   159→    if (!loading && !user) {
   160→      router.push('/login');
   161→    }
   162→  }, [user, loading, router]);
   163→
   164→  const handleLogout = async () => {
   165→    try {
   166→      await logout();
   167→      router.push('/login');
   168→    } catch (err) {
   169→      console.error('Logout failed:', err);
   170→    }
   171→  };
   172→
   173→  const handleStartChat = async (memberId: string, dmConversationId?: string) => {
   174→    try {
   175→      // === Step 1: Immediate optimistic update ===
   176→      // Update selected DM state and highlight immediately
   177→      setSelectedChat(memberId);
   178→      // Clear selected channel
   179→      setSelectedChannel(undefined);
   180→
   181→      // === Step 2: Immediate page navigation ===
   182→      // Use router.push for navigation (still use memberId path to be compatible with existing routes)
   183→      const targetUrl = `/dm/${memberId}`;
   184→      router.push(targetUrl);
   185→
   186→      // === Step 3: Create/get conversation in background (non-blocking) ===
   187→      // If conversationId is not provided, create or get DM conversation
   188→      if (!dmConversationId) {
   189→        const createConversation = async () => {
   190→          try {
   191→            const resp = await fetch('/api/conversations/dm', {
   192→              method: 'POST',
   193→              headers: { 'Content-Type': 'application/json' },
   194→              credentials: 'include',
   195→              body: JSON.stringify({ userId: memberId })
   196→            });
   197→
   198→            if (resp.ok) {
   199→              const conversation = await resp.json();
   200→
   201→              // Dispatch global event to notify DirectMessages to optimistically add new conversation
   202→              try {
   203→                window.dispatchEvent(new CustomEvent('dm-created', { detail: conversation }));
   204→              } catch (e) {
   205→                console.warn('Cannot dispatch dm-created event', e);
   206→              }
   207→            }
   208→          } catch (err) {
   209→            console.error('Background conversation creation failed:', err);
   210→          }
   211→        };
   212→
   213→        // Return immediately without waiting for result
   214→        createConversation();
   215→      }
   216→    } catch (err) {
   217→      console.error('Error starting DM:', err);
   218→      // Even if there's an error, ensure state update and navigation
   219→      setSelectedChat(memberId);
   220→      setSelectedChannel(undefined);
   221→      router.push(`/dm/${memberId}`);
   222→    }
   223→  };
