     1→'use client';
     2→
     3→import { create } from 'zustand';
     4→import { Message } from '@/types/message';
     5→
     6→interface ThreadSummary {
     7→  id: string;
     8→  content: string;
     9→  userId: string;
    10→  user?: {
    11→    id: string;
    12→    displayName: string;
    13→    avatarUrl?: string;
    14→  };
    15→  threadReplies?: Message[];
    16→  _count?: {
    17→    threadReplies: number;
    18→  };
    19→  unreadCount: number;
    20→  lastReadAt: string | null;
    21→  lastReplyAt?: string | null;
    22→}
    23→
    24→interface ThreadStore {
    25→  // State
    26→  activeThreadId: string | null;
    27→  activeThreadMessage: Message | null;
    28→  threadPanelOpen: boolean;
    29→  unreadThreads: ThreadSummary[];
    30→  unreadCount: number;
    31→  isLoading: boolean;
    32→
    33→  // Actions
    34→  setActiveThread: (id: string | null, message?: Message | null) => void;
    35→  closeThread: () => void;
    36→  toggleThreadPanel: () => void;
    37→  setUnreadThreads: (threads: ThreadSummary[]) => void;
    38→  addUnreadThread: (thread: ThreadSummary) => void;
    39→  removeUnreadThread: (threadId: string) => void;
    40→  updateThreadReplyCount: (threadId: string, count: number) => void;
    41→  setUnreadCount: (count: number) => void;
    42→  markThreadAsRead: (threadId: string) => void;
    43→  setLoading: (loading: boolean) => void;
    44→}
    45→
    46→export const useThreadStore = create<ThreadStore>((set, get) => ({
    47→  // Initial state
    48→  activeThreadId: null,
    49→  activeThreadMessage: null,
    50→  threadPanelOpen: false,
    51→  unreadThreads: [],
    52→  unreadCount: 0,
    53→  isLoading: false,
    54→
    55→  // Actions
    56→  setActiveThread: (id, message) => {
    57→    set({
    58→      activeThreadId: id,
    59→      activeThreadMessage: message || null,
    60→      threadPanelOpen: !!id,
    61→    });
    62→  },
    63→
    64→  closeThread: () => {
    65→    set({
    66→      activeThreadId: null,
    67→      activeThreadMessage: null,
    68→      threadPanelOpen: false,
    69→    });
    70→  },
    71→
    72→  toggleThreadPanel: () => {
    73→    set((state) => ({
    74→      threadPanelOpen: !state.threadPanelOpen,
    75→    }));
    76→  },
    77→
    78→  setUnreadThreads: (threads) => {
    79→    set({
    80→      unreadThreads: threads,
    81→      unreadCount: threads.reduce((sum, thread) => sum + thread.unreadCount, 0),
    82→    });
    83→  },
    84→
    85→  addUnreadThread: (thread) => {
    86→    set((state) => {
    87→      const exists = state.unreadThreads.find((t) => t.id === thread.id);
    88→      if (exists) {
    89→        return state;
    90→      }
    91→      return {
    92→        unreadThreads: [thread, ...state.unreadThreads],
    93→        unreadCount: state.unreadCount + thread.unreadCount,
    94→      };
    95→    });
    96→  },
    97→
    98→  removeUnreadThread: (threadId) => {
    99→    set((state) => {
   100→      const thread = state.unreadThreads.find((t) => t.id === threadId);
   101→      if (!thread) return state;
   102→
   103→      return {
   104→        unreadThreads: state.unreadThreads.filter((t) => t.id !== threadId),
   105→        unreadCount: Math.max(0, state.unreadCount - thread.unreadCount),
   106→      };
   107→    });
   108→  },
   109→
   110→  updateThreadReplyCount: (threadId, count) => {
   111→    set((state) => ({
   112→      unreadThreads: state.unreadThreads.map((thread) =>
   113→        thread.id === threadId
   114→          ? { ...thread, _count: { threadReplies: count } }
   115→          : thread
   116→      ),
   117→    }));
   118→  },
   119→
   120→  setUnreadCount: (count) => {
   121→    set({ unreadCount: count });
   122→  },
   123→
   124→  markThreadAsRead: (threadId) => {
   125→    set((state) => ({
