    61→// Fix #1: Don't append /socket.io to URL — Socket.IO handles path internally
    62→function getServerUrl(): string {
    63→  const appUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";
    64→  // Socket.IO client expects the server origin, not a ws:// URL
    65→  // It handles protocol upgrade internally
    66→  return appUrl;
    67→}
    68→
    69→function getWsToken(): string | null {
    70→  if (typeof document === "undefined") return null;
    71→  const cookies = document.cookie.split(";");
    72→  for (const cookie of cookies) {
    73→    const [name, value] = cookie.trim().split("=");
    74→    if (name === "ws_token") return value;
    75→  }
