    96→    // If there's an existing disconnected socket, clean it up first
    97→    if (socketRef.current) {
    98→      socketRef.current.removeAllListeners();
    99→      socketRef.current.disconnect();
   100→      socketRef.current = null;
   101→    }
   102→
   103→    isConnecting.current = true;
   104→
   105→    const serverUrl = getServerUrl();
   106→
   107→    // Fix #2: Remove forceNew — allow connection reuse
   108→    // Fix #4: Remove autoConnect:false — we call connect() explicitly
   109→    // Fix #10: Remove hardcoded secure:true — let Socket.IO infer from URL
   110→    const inst = io(serverUrl, {
   111→      auth: { token },
   112→      transports: ["websocket", "polling"],
   113→      reconnection: true,
   114→      reconnectionDelay: 1000,
   115→      reconnectionDelayMax: 10000,
   116→      reconnectionAttempts: 10,
   117→      timeout: 20000,
   118→      path: "/socket.io",
   119→    });
   120→
   121→    inst.on("connect", () => {
   122→      console.log("[WS] Connected, id:", inst.id);
   123→      setIsConnected(true);
   124→      setConnectionStatus("connected");
   125→      isConnecting.current = false;
   126→      // Clear fallback timer on successful connect
   127→      if (fallbackTimer.current) {
   128→        clearTimeout(fallbackTimer.current);
   129→        fallbackTimer.current = null;
   130→      }
   131→    });
   132→
   133→    inst.on("disconnect", (reason) => {
   134→      console.log("[WS] Disconnected:", reason);
   135→      setIsConnected(false);
   136→      setConnectionStatus("disconnected");
   137→      isConnecting.current = false;
   138→      // Fix: server-initiated disconnect needs manual reconnect
   139→      if (reason === "io server disconnect") {
