   142→    });
   143→
   144→    inst.on("reconnect_attempt", (attempt) => {
   145→      console.log("[WS] Reconnect attempt", attempt);
   146→      setConnectionStatus("reconnecting");
   147→    });
   148→
   149→    inst.on("reconnect", () => {
   150→      console.log("[WS] Reconnected");
   151→      setIsConnected(true);
   152→      setConnectionStatus("connected");
   153→      isConnecting.current = false;
   154→    });
   155→
   156→    // Fix #6: Recovery after max reconnect attempts exhausted
   157→    inst.on("reconnect_failed", () => {
   158→      console.log("[WS] Reconnect failed, will retry in 30s");
   159→      setConnectionStatus("error");
   160→      setIsConnected(false);
   161→      isConnecting.current = false;
   162→      // Exponential fallback: try again after 30 seconds
   163→      fallbackTimer.current = setTimeout(() => {
