     1→import { NextRequest, NextResponse } from 'next/server';
     2→import { prisma } from '@/lib/prisma';
     3→import { verifyToken } from '@/lib/auth';
     4→import { unauthorizedResponse } from '@/lib/api-response';
     5→import { PrismaClient } from '@prisma/client';
     6→
     7→type PrismaTransaction = Omit<PrismaClient, '$connect' | '$disconnect' | '$on' | '$transaction' | '$use' | '$extends'>;
     8→
     9→export async function GET(
    10→  request: NextRequest,
    11→  { params }: { params: { userId: string } }
    12→) {
    13→  try {
    14→    const token = request.cookies.get('auth_token')?.value;
    15→
    16→    if (!token) {
    17→      return NextResponse.json(
    18→        unauthorizedResponse(),
    19→        { status: 401 }
    20→      );
    21→    }
    22→
    23→    // Verify token
    24→    const decoded = verifyToken(token);
    25→    if (!decoded) {
    26→      return NextResponse.json(
    27→        unauthorizedResponse('Invalid token'),
    28→        { status: 401 }
    29→      );
    30→    }
    31→
    32→    const currentUserId = decoded.userId;
    33→    const targetUserId = params.userId;
    34→
    35→    // Validate user ID format (must be UUID format)
    36→    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    37→    if (!uuidRegex.test(targetUserId)) {
    38→      return NextResponse.json(
    39→        { error: 'Invalid user ID format' },
    40→        { status: 400 }
    41→      );
    42→    }
    43→
    44→    // Verify target user exists
    45→    const targetUser = await prisma.user.findUnique({
    46→      where: { id: targetUserId },
    47→      select: { id: true, displayName: true }
    48→    });
    49→
    50→    if (!targetUser) {
    51→      return NextResponse.json(
    52→        { error: 'User not found' },
    53→        { status: 404 }
    54→      );
    55→    }
    56→
    57→    // Verify current user exists
    58→    const currentUser = await prisma.user.findUnique({
    59→      where: { id: currentUserId },
    60→      select: { id: true, displayName: true }
    61→    });
    62→
    63→    if (!currentUser) {
    64→      return NextResponse.json(
    65→        { error: 'Current user not found' },
    66→        { status: 404 }
    67→      );
    68→    }
    69→
    70→    if (currentUserId === targetUserId) {
    71→      // If it's a conversation with yourself, return a special conversation object
    72→      return NextResponse.json({
    73→        id: `self-${currentUserId}`,
    74→        createdById: currentUserId,
    75→        lastMessageAt: new Date(),
    76→        createdAt: new Date(),
    77→        updatedAt: new Date(),
    78→        isOwnSpace: true,
    79→        members: [
    80→          {
    81→            user: {
    82→              id: currentUserId,
    83→              displayName: 'You',
    84→              avatarUrl: null,
    85→              realName: null
    86→            }
    87→          }
    88→        ]
    89→      });
    90→    }
    91→
    92→    // Find existing DM conversation (conversation between two users)
    93→    const existingConversation = await prisma.dMConversation.findFirst({
    94→      where: {
    95→        AND: [
    96→          {
    97→            members: {
    98→              some: {
    99→                userId: currentUserId
   100→              }
   101→            }
   102→          },
   103→          {
   104→            members: {
   105→              some: {
   106→                userId: targetUserId
   107→              }
   108→            }
   109→          }
   110→        ]
   111→      },
   112→      include: {
   113→        members: {
   114→          select: {
   115→            id: true,
   116→            isStarred: true,
   117→            unreadCount: true,
   118→            lastReadAt: true,
   119→            user: {
   120→              select: {
   121→                id: true,
   122→                displayName: true,
   123→                avatarUrl: true,
   124→                realName: true,
   125→                status: true,
   126→                isOnline: true,
   127→                email: true
   128→              }
   129→            }
   130→          }
   131→        },
   132→        messages: {
   133→          take: 1,
   134→          orderBy: {
   135→            createdAt: 'desc'
   136→          },
   137→          include: {
   138→            user: {
   139→              select: {
   140→                id: true,
   141→                displayName: true,
   142→                avatarUrl: true
   143→              }
   144→            }
   145→          }
   146→        }
   147→      }
   148→    });
   149→
   150→    if (existingConversation) {
   151→      return NextResponse.json(existingConversation);
   152→    }
   153→
   154→    // If not exists, create new DM conversation
   155→    const newConversation = await prisma.$transaction(async (tx: PrismaTransaction) => {
   156→      // Verify users exist again (inside transaction)
   157→      const [currentUserExists, targetUserExists] = await Promise.all([
   158→        tx.user.findUnique({
   159→          where: { id: currentUserId },
   160→          select: { id: true }
   161→        }),
