import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { verifyToken } from '@/lib/auth';
import { unauthorizedResponse } from '@/lib/api-response';
import { PrismaClient } from '@prisma/client';

type PrismaTransaction = Omit<PrismaClient, '$connect' | '$disconnect' | '$on' | '$transaction' | '$use' | '$extends'>;

export async function GET(
  request: NextRequest,
  { params }: { params: { userId: string } }
) {
  try {
    const token = request.cookies.get('auth_token')?.value;

    if (!token) {
      return NextResponse.json(
        unauthorizedResponse(),
        { status: 401 }
      );
    }

    // Verify token
    const decoded = verifyToken(token);
    if (!decoded) {
      return NextResponse.json(
        unauthorizedResponse('Invalid token'),
        { status: 401 }
      );
    }

    const currentUserId = decoded.userId;
    const targetUserId = params.userId;

    // Validate user ID format (must be UUID format)
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(targetUserId)) {
      return NextResponse.json(
        { error: 'Invalid user ID format' },
        { status: 400 }
      );
    }

    // Verify target user exists
    const targetUser = await prisma.user.findUnique({
      where: { id: targetUserId },
      select: { id: true, displayName: true }
    });

    if (!targetUser) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    // Verify current user exists
    const currentUser = await prisma.user.findUnique({
      where: { id: currentUserId },
      select: { id: true, displayName: true }
    });

    if (!currentUser) {
      return NextResponse.json(
        { error: 'Current user not found' },
        { status: 404 }
      );
    }

    if (currentUserId === targetUserId) {
      // If it's a conversation with yourself, return a special conversation object
      return NextResponse.json({
        id: `self-${currentUserId}`,
        createdById: currentUserId,
        lastMessageAt: new Date(),
        createdAt: new Date(),
        updatedAt: new Date(),
        isOwnSpace: true,
        members: [
          {
            user: {
              id: currentUserId,
              displayName: 'You',
              avatarUrl: null,
              realName: null
            }
          }
        ]
      });
    }

    // Find existing DM conversation (conversation between two users)
    const existingConversation = await prisma.dMConversation.findFirst({
      where: {
        AND: [
          {
            members: {
              some: {
                userId: currentUserId
              }
            }
          },
          {
            members: {
              some: {
                userId: targetUserId
              }
            }
          }
        ]
      },
      include: {
        members: {
          select: {
            id: true,
            isStarred: true,
            unreadCount: true,
            lastReadAt: true,
            user: {
              select: {
                id: true,
                displayName: true,
                avatarUrl: true,
                realName: true,
                status: true,
                isOnline: true,
                email: true
              }
            }
          }
        },
        messages: {
          take: 1,
          orderBy: {
            createdAt: 'desc'
          },
          include: {
            user: {
              select: {
                id: true,
                displayName: true,
                avatarUrl: true
              }
            }
          }
        }
      }
    });

    if (existingConversation) {
      return NextResponse.json(existingConversation);
    }

    // If not exists, create new DM conversation
    const newConversation = await prisma.$transaction(async (tx: PrismaTransaction) => {
      // Verify users exist again (inside transaction)
      const [currentUserExists, targetUserExists] = await Promise.all([
        tx.user.findUnique({
          where: { id: currentUserId },
          select: { id: true }
        }),
        tx.user.findUnique({
          where: { id: targetUserId },
          select: { id: true }
        })
      ]);

      if (!currentUserExists) {
        throw new Error('Current user not found');
      }

      if (!targetUserExists) {
        throw new Error('Target user not found');
      }

      // Create new conversation
      const conversation = await tx.dMConversation.create({
        data: {
          createdById: currentUserId,
          members: {
            create: [
              {
                userId: currentUserId
              },
              {
                userId: targetUserId
              }
            ]
          }
        },
        include: {
          members: {
            select: {
              id: true,
              isStarred: true,
              unreadCount: true,
              lastReadAt: true,
              user: {
                select: {
                  id: true,
                  displayName: true,
                  avatarUrl: true,
                  realName: true,
                  status: true,
                  isOnline: true,
                  email: true
                }
              }
            }
          },
          messages: {
            take: 1,
            orderBy: {
              createdAt: 'desc'
            }
          }
        }
      });

      return conversation;
    });

    return NextResponse.json(newConversation);
  } catch (error: any) {
    console.error('Error getting DM conversation:', error);

    // Provide more specific error information
    if (error.code === 'P2003') {
      return NextResponse.json(
        { error: 'Foreign key constraint error: user not found' },
        { status: 400 }
      );
    }

    if (error.message?.includes('not found')) {
      return NextResponse.json(
        { error: error.message },
        { status: 404 }
      );
    }

    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

